                    vjl_zz += (al2 * (aj2 * (vgx[(h & 2 ? (h & 1 ? 2296 : 1976) : (h & 1 ? 1912 : 1656))] - zjzi * vgx[(h & 2 ? (h & 1 ? 2288 : 1968) : (h & 1 ? 1904 : 1648))] - zlzk * (vgx[(h & 2 ? (h & 1 ? 2232 : 1912) : (h & 1 ? 1848 : 1592))] - zjzi * vgx[(h & 2 ? (h & 1 ? 2224 : 1904) : (h & 1 ? 1840 : 1584))])) - 1.0 * (vgx[(h & 2 ? (h & 1 ? 2256 : 1936) : (h & 1 ? 1872 : 1616))] - zlzk * vgx[(h & 2 ? (h & 1 ? 2192 : 1872) : (h & 1 ? 1808 : 1552))])) - (h & 2 ? (h & 1 ? 2.0 : 1.0) : (h & 1 ? 1.0 : 0.0)) * (aj2 * (vgx[(h & 2 ? (h & 1 ? 1976 : 1656) : (h & 1 ? 1592 : 1584))] - zjzi * vgx[(h & 2 ? (h & 1 ? 1968 : 1648) : 1584)]) - 1.0 * vgx[(h & 2 ? (h & 1 ? 1936 : 1616) : (h & 1 ? 1552 : 1584))])) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    w = dd_cache[(h & 2 ? (h & 1 ? 5184 : 3880) : (h & 1 ? 4456 : 1144))] * vgx[(h & 2 ? (h & 1 ? 768 : 1024) : (h & 1 ? 768 : 1088))];
                    S = w * vgx[(h & 2 ? (h & 1 ? 688 : 64) : (h & 1 ? 128 : 320))];
                    T0 = vgx[(h & 2 ? (h & 1 ? 4000 : 2496) : (h & 1 ? 2688 : 3072))] * w;
                    T1 = vgx[(h & 2 ? (h & 1 ? 4008 : 2504) : (h & 1 ? 2696 : 3080))] * w;
                    T2 = vgx[(h & 2 ? (h & 1 ? 4016 : 2512) : (h & 1 ? 2704 : 3088))] * w;
                    T3 = vgx[(h & 2 ? (h & 1 ? 4024 : 2520) : (h & 1 ? 2712 : 3096))] * w;
                    Ai = vgx[(h & 2 ? (h & 1 ? 7456 : 6688) : (h & 1 ? 7072 : 5920))];
                    Aj = vgx[(h & 2 ? (h & 1 ? 7464 : 6696) : (h & 1 ? 7080 : 5928))];
                    Ak = vgx[(h & 2 ? (h & 1 ? 7472 : 6704) : (h & 1 ? 7088 : 5936))];
                    Al = vgx[(h & 2 ? (h & 1 ? 7480 : 6712) : (h & 1 ? 7096 : 5944))];
                    vik_zz += (ak2 * (ai2 * vgx[(h & 2 ? (h & 1 ? 2296 : 1976) : (h & 1 ? 2168 : 1656))] - 2.0 * vgx[(h & 2 ? (h & 1 ? 2280 : 1960) : (h & 1 ? 2152 : 1640))]) - (h & 2 ? (h & 1 ? 2.0 : 1.0) : 0.0) * (ai2 * vgx[(h & 2 ? (h & 1 ? 2168 : 1848) : (h & 1 ? 2096 : 1584))] - 2.0 * vgx[(h & 2 ? (h & 1 ? 2152 : 1832) : (h & 1 ? 2096 : 1584))])) * S;
                    vjk_zz += (ak2 * (aj2 * (vgx[(h & 2 ? (h & 1 ? 2296 : 1976) : (h & 1 ? 2168 : 1656))] - zjzi * vgx[(h & 2 ? (h & 1 ? 2288 : 1968) : (h & 1 ? 2160 : 1648))]) - 1.0 * vgx[(h & 2 ? (h & 1 ? 2256 : 1936) : (h & 1 ? 2128 : 1616))]) - (h & 2 ? (h & 1 ? 2.0 : 1.0) : 0.0) * (aj2 * (vgx[(h & 2 ? (h & 1 ? 2168 : 1848) : (h & 1 ? 2096 : 1584))] - zjzi * vgx[(h & 2 ? (h & 1 ? 2160 : 1840) : (h & 1 ? 2096 : 1584))]) - 1.0 * vgx[(h & 2 ? (h & 1 ? 2128 : 1808) : (h & 1 ? 2096 : 1584))])) * S;
                    vil_zz += (al2 * (ai2 * (vgx[(h & 2 ? (h & 1 ? 2296 : 1976) : (h & 1 ? 2168 : 1656))] - zlzk * vgx[(h & 2 ? (h & 1 ? 2232 : 1912) : (h & 1 ? 2104 : 1592))]) - 2.0 * (vgx[(h & 2 ? (h & 1 ? 2280 : 1960) : (h & 1 ? 2152 : 1640))] - zlzk * vgx[(h & 2 ? (h & 1 ? 2216 : 1896) : (h & 1 ? 2088 : 1576))])) - (h & 2 ? (h & 1 ? 2.0 : 1.0) : (h & 1 ? 2.0 : 0.0)) * (ai2 * vgx[(h & 2 ? (h & 1 ? 1976 : 1656) : (h & 1 ? 1848 : 1584))] - 2.0 * vgx[(h & 2 ? (h & 1 ? 1960 : 1640) : (h & 1 ? 1832 : 1584))])) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[(h & 2 ? (h & 1 ? 2296 : 1976) : (h & 1 ? 2168 : 1656))] - zjzi * vgx[(h & 2 ? (h & 1 ? 2288 : 1968) : (h & 1 ? 2160 : 1648))] - zlzk * (vgx[(h & 2 ? (h & 1 ? 2232 : 1912) : (h & 1 ? 2104 : 1592))] - zjzi * vgx[(h & 2 ? (h & 1 ? 2224 : 1904) : (h & 1 ? 2096 : 1584))])) - 1.0 * (vgx[(h & 2 ? (h & 1 ? 2256 : 1936) : (h & 1 ? 2128 : 1616))] - zlzk * vgx[(h & 2 ? (h & 1 ? 2192 : 1872) : (h & 1 ? 2064 : 1552))])) - (h & 2 ? (h & 1 ? 2.0 : 1.0) : (h & 1 ? 2.0 : 0.0)) * (aj2 * (vgx[(h & 2 ? (h & 1 ? 1976 : 1656) : (h & 1 ? 1848 : 1584))] - zjzi * vgx[(h & 2 ? (h & 1 ? 1968 : 1648) : (h & 1 ? 1840 : 1584))]) - 1.0 * vgx[(h & 2 ? (h & 1 ? 1936 : 1616) : (h & 1 ? 1808 : 1584))])) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
