// type12 (dp|pp): 162 outputs, 24 tuples per direction, 32 threads x 8 quartets per block, g_size 108
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip2_type12_gen_2111(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
