                        s2 = cpx*s1 + 3 * b01 *s0;
                        _gx[512] = s2;
                        s0 = _gx[16];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[144] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[128];
                        _gx[272] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 1 * b00 * _gx[256];
                        _gx[400] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 1 * b00 * _gx[384];
                        _gx[528] = s2;
                        s0 = _gx[32];
