        atomicAdd(ejk + (ka*natm+la)*9 + 1, vkl_xy);
        atomicAdd(ejk + (ka*natm+la)*9 + 2, vkl_xz);
        atomicAdd(ejk + (ka*natm+la)*9 + 3, vkl_yx);
        atomicAdd(ejk + (ka*natm+la)*9 + 4, vkl_yy);
        atomicAdd(ejk + (ka*natm+la)*9 + 5, vkl_yz);
        atomicAdd(ejk + (ka*natm+la)*9 + 6, vkl_zx);
        atomicAdd(ejk + (ka*natm+la)*9 + 7, vkl_zy);
        atomicAdd(ejk + (ka*natm+la)*9 + 8, vkl_zz);
        atomicAdd(ejk + (ka*natm+ka)*9 + 0, vkk_xx*.5);
        atomicAdd(ejk + (ka*natm+ka)*9 + 3, vkk_xy);
        atomicAdd(ejk + (ka*natm+ka)*9 + 4, vkk_yy*.5);
        atomicAdd(ejk + (ka*natm+ka)*9 + 6, vkk_xz);
        atomicAdd(ejk + (ka*natm+ka)*9 + 7, vkk_yz);
        atomicAdd(ejk + (ka*natm+ka)*9 + 8, vkk_zz*.5);
        atomicAdd(ejk + (la*natm+la)*9 + 0, vll_xx*.5);
        atomicAdd(ejk + (la*natm+la)*9 + 3, vll_xy);
        atomicAdd(ejk + (la*natm+la)*9 + 4, vll_yy*.5);
        atomicAdd(ejk + (la*natm+la)*9 + 6, vll_xz);
        atomicAdd(ejk + (la*natm+la)*9 + 7, vll_yz);
        atomicAdd(ejk + (la*natm+la)*9 + 8, vll_zz*.5);
    }
    int ia = bas[ish*BAS_SLOTS+ATOM_OF];
    int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
    int natm = envs.natm;
    double *ejk = jk.ejk;
    atomicAdd(ejk + (ia*natm+ja)*9 + 0, vij_xx);
    atomicAdd(ejk + (ia*natm+ja)*9 + 1, vij_xy);
    atomicAdd(ejk + (ia*natm+ja)*9 + 2, vij_xz);
    atomicAdd(ejk + (ia*natm+ja)*9 + 3, vij_yx);
    atomicAdd(ejk + (ia*natm+ja)*9 + 4, vij_yy);
    atomicAdd(ejk + (ia*natm+ja)*9 + 5, vij_yz);
    atomicAdd(ejk + (ia*natm+ja)*9 + 6, vij_zx);
    atomicAdd(ejk + (ia*natm+ja)*9 + 7, vij_zy);
    atomicAdd(ejk + (ia*natm+ja)*9 + 8, vij_zz);
    atomicAdd(ejk + (ia*natm+ia)*9 + 0, vii_xx*.5);
    atomicAdd(ejk + (ia*natm+ia)*9 + 3, vii_xy);
    atomicAdd(ejk + (ia*natm+ia)*9 + 4, vii_yy*.5);
    atomicAdd(ejk + (ia*natm+ia)*9 + 6, vii_xz);
    atomicAdd(ejk + (ia*natm+ia)*9 + 7, vii_yz);
    atomicAdd(ejk + (ia*natm+ia)*9 + 8, vii_zz*.5);
    atomicAdd(ejk + (ja*natm+ja)*9 + 0, vjj_xx*.5);
    atomicAdd(ejk + (ja*natm+ja)*9 + 3, vjj_xy);
    atomicAdd(ejk + (ja*natm+ja)*9 + 4, vjj_yy*.5);
    atomicAdd(ejk + (ja*natm+ja)*9 + 6, vjj_xz);
    atomicAdd(ejk + (ja*natm+ja)*9 + 7, vjj_yz);
    atomicAdd(ejk + (ja*natm+ja)*9 + 8, vjj_zz*.5);
}
}

// type3 (ds|pp): 54 outputs, 12 tuples per direction, 8 threads x 32 quartets per block, g_size 24
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip2_type3_gen_2011(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 32;
    constexpr int gout_stride = 8;
    int t_id = gout_id * nsq_per_block + sq_id;
    int threads = nsq_per_block * gout_stride;
    int nbas = envs.nbas;
    int *bas = envs.bas;
    double *env = envs.env;
    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    int kprim = bounds.kprim;
    int lprim = bounds.lprim;
    int nroots = bounds.nroots;
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    // the g arrays of the three directions, then the first-derivative factors of every tuple
    double *gx = shared_memory + nsq_per_block * 6 + sq_id;
    double *rw = shared_memory + nsq_per_block * 222 + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (222+nroots*2);

    uint32_t *bas_kl_idx = pool + worker_id * QUEUE_DEPTH;
    double *dd_cache = dd_pool + worker_id * 1728 + sq_id;
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;

    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        // another thread of this quartet may still read the previous task's dd_cache
        __syncthreads();
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        if (gout_id == 0) {
            rlrk[0] = xlxk;
            rlrk[32] = ylyk;
            rlrk[2*32] = zlzk;
        }
        double vik_xx = 0;
        double vik_xy = 0;
        double vik_xz = 0;
        double vik_yx = 0;
        double vik_yy = 0;
        double vik_yz = 0;
        double vik_zx = 0;
        double vik_zy = 0;
        double vik_zz = 0;
        double vjk_xx = 0;
        double vjk_xy = 0;
        double vjk_xz = 0;
        double vjk_yx = 0;
        double vjk_yy = 0;
        double vjk_yz = 0;
        double vjk_zx = 0;
        double vjk_zy = 0;
        double vjk_zz = 0;
        double vil_xx = 0;
        double vil_xy = 0;
        double vil_xz = 0;
        double vil_yx = 0;
        double vil_yy = 0;
        double vil_yz = 0;
        double vil_zx = 0;
        double vil_zy = 0;
        double vil_zz = 0;
        double vjl_xx = 0;
        double vjl_xy = 0;
        double vjl_xz = 0;
        double vjl_yx = 0;
        double vjl_yy = 0;
        double vjl_yz = 0;
        double vjl_zx = 0;
        double vjl_zy = 0;
        double vjl_zz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 54; n+=8) {
                int i = n % 6;
                int j = n / 6 % 1;
                int k = n / 6 % 3;
                int l = n / 18;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_il] + dm[_jl] * dm[_ik]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 54; n+=8) {
                int i = n % 6;
                int j = n / 6 % 1;
                int k = n / 6 % 3;
                int l = n / 18;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += dm [_jk] * dm [_il] + dm [_jl] * dm [_ik];
                    dd += dmb[_jk] * dmb[_il] + dmb[_jl] * dmb[_ik];
                    dd *= jk.k_factor;
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            __syncthreads();
            if (gout_id == 0) {
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                gx[0] = ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
                double zpq = zij - zkl;
                double theta = aij * akl / (aij + akl);
                double rr = xpq * xpq + ypq * ypq + zpq * zpq;
                __syncthreads();
                if (gout_id == 0) {
                    Rpq[0] = xpq;
                    Rpq[32] = ypq;
                    Rpq[2*32] = zpq;
                    double cicj = cicj_cache[ijp];
                    gx[24*32] = cicj / (aij*akl*sqrt(aij+akl));
                }
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 8, gout_id);
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*64];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    for (int n = gout_id; n < 3; n += 8) {
                        if (n == 2) {
                            gx[1536] = rw[irys*64+32];
                        }
                        double *_gx = gx + n * 768;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[32] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[64] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[96] = s2;
                        double xlxk = rlrk[n*32];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[128] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[256] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        _gx[384] = s2;
                        s0 = _gx[32];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[160] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[128];
                        _gx[288] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 1 * b00 * _gx[256];
                        _gx[416] = s2;
                        s0 = _gx[64];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[32];
                        _gx[192] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[160];
                        _gx[320] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 2 * b00 * _gx[288];
                        _gx[448] = s2;
                        s0 = _gx[96];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[64];
                        _gx[224] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 3 * b00 * _gx[192];
                        _gx[352] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 3 * b00 * _gx[320];
                        _gx[480] = s2;
                        s1 = _gx[384];
                        s0 = _gx[256];
                        _gx[640] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[128];
                        _gx[512] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[0];
                        _gx[384] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[416];
                        s0 = _gx[288];
                        _gx[672] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[160];
                        _gx[544] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[32];
                        _gx[416] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[448];
                        s0 = _gx[320];
                        _gx[704] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[192];
                        _gx[576] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[64];
                        _gx[448] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[480];
                        s0 = _gx[352];
                        _gx[736] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[224];
                        _gx[608] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[96];
                        _gx[480] = s1 - xlxk * s0;
                        s1 = s0;
                    }
                    __syncthreads();
                    for (int e = gout_id; e < 36; e += 8) {
                        int d = e / 12;
                        int t = e - d * 12;
                        int ti = t % 3;
                        int tj = t / 3 % 1;
                        int tk = t / 3 % 2;
                        int tl = t / 6;
                        double *_g = gx + (d * 24 + ti + tj * 4 + tk * 4 + tl * 12) * 32;
                        double *_t = gx + (72 + e * 4) * 32;
                        _t[0] = ai2 * _g[32] - (ti ? ti * _g[-32] : 0.);
                        _t[32] = aj2 * (_g[32] - rjri[d] * _g[0]) - (tj ? tj * _g[-128] : 0.);
                        _t[64] = ak2 * _g[128] - (tk ? tk * _g[-128] : 0.);
                        _t[96] = al2 * (_g[128] - rlrk[d*32] * _g[0]) - (tl ? tl * _g[-384] : 0.);
                    }
                    __syncthreads();
                    volatile double *vgx = gx;
                    double w, S, T0, T1, T2, T3, Ai, Aj, Ak, Al;
                    switch (gout_id / 1) {
                    case 0:
                    w = dd_cache[864] * vgx[1536];
                    S = w * vgx[1344];
                    T0 = vgx[5248] * w;
                    T1 = vgx[5280] * w;
                    T2 = vgx[5312] * w;
                    T3 = vgx[5344] * w;
                    w = dd_cache[896] * vgx[1568];
                    S += w * vgx[1312];
                    T0 += vgx[5120] * w;
                    T1 += vgx[5152] * w;
                    T2 += vgx[5184] * w;
                    T3 += vgx[5216] * w;
                    w = dd_cache[928] * vgx[1600];
                    S += w * vgx[1280];
                    T0 += vgx[4992] * w;
                    T1 += vgx[5024] * w;
                    T2 += vgx[5056] * w;
                    T3 += vgx[5088] * w;
                    w = dd_cache[1056] * vgx[1664];
                    S += w * vgx[1216];
                    T0 += vgx[4864] * w;
                    T1 += vgx[4896] * w;
                    T2 += vgx[4928] * w;
                    T3 += vgx[4960] * w;
                    w = dd_cache[1088] * vgx[1696];
                    S += w * vgx[1184];
                    T0 += vgx[4736] * w;
                    T1 += vgx[4768] * w;
                    T2 += vgx[4800] * w;
                    T3 += vgx[4832] * w;
                    w = dd_cache[1120] * vgx[1728];
                    S += w * vgx[1152];
                    T0 += vgx[4608] * w;
                    T1 += vgx[4640] * w;
                    T2 += vgx[4672] * w;
                    T3 += vgx[4704] * w;
                    w = dd_cache[1440] * vgx[1920];
                    S += w * vgx[960];
                    T0 += vgx[4480] * w;
                    T1 += vgx[4512] * w;
                    T2 += vgx[4544] * w;
                    T3 += vgx[4576] * w;
                    w = dd_cache[1472] * vgx[1952];
                    S += w * vgx[928];
                    T0 += vgx[4352] * w;
                    T1 += vgx[4384] * w;
                    T2 += vgx[4416] * w;
                    T3 += vgx[4448] * w;
                    w = dd_cache[1504] * vgx[1984];
                    S += w * vgx[896];
                    T0 += vgx[4224] * w;
                    T1 += vgx[4256] * w;
                    T2 += vgx[4288] * w;
                    T3 += vgx[4320] * w;
                    w = dd_cache[1632] * vgx[2048];
                    S += w * vgx[832];
                    T0 += vgx[4096] * w;
                    T1 += vgx[4128] * w;
                    T2 += vgx[4160] * w;
                    T3 += vgx[4192] * w;
                    w = dd_cache[1664] * vgx[2080];
                    S += w * vgx[800];
                    T0 += vgx[3968] * w;
                    T1 += vgx[4000] * w;
                    T2 += vgx[4032] * w;
                    T3 += vgx[4064] * w;
