                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*64];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[64] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[128] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[192] = s2;
                        double xlxk = rlrk[n*64];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*64];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[256] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[512] = s2;
                        s0 = _gx[64];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[320] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[256];
                        _gx[576] = s2;
                        s0 = _gx[128];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[64];
                        _gx[384] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[320];
                        _gx[640] = s2;
                        s0 = _gx[192];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[128];
                        _gx[448] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 3 * b00 * _gx[384];
                        _gx[704] = s2;
                    }
                    __syncthreads();
                    for (int e = gout_id; e < 18; e += 4) {
                        int d = e / 6;
                        int t = e - d * 6;
                        int ti = t % 3;
                        int tj = t / 3 % 1;
                        int tk = t / 3 % 2;
                        int tl = t / 6;
                        double *_g = gx + (d * 12 + ti + tj * 4 + tk * 4 + tl * 12) * 64;
                        double *_t = gx + (36 + e * 4) * 64;
                        _t[0] = ai2 * _g[64] - (ti ? ti * _g[-64] : 0.);
                        _t[64] = aj2 * (_g[64] - rjri[d] * _g[0]) - (tj ? tj * _g[-256] : 0.);
                        _t[128] = ak2 * _g[256] - (tk ? tk * _g[-256] : 0.);
                        _t[192] = al2 * (_g[256] - rlrk[d*64] * _g[0]) - (tl ? tl * _g[-768] : 0.);
                    }
                    __syncthreads();
                    volatile double *vgx = gx;
                    double w, S, T0, T1, T2, T3, Ai, Aj, Ak, Al;
                    switch (gout_id / 1) {
                    case 0:
                    w = dd_cache[576] * vgx[1536];
                    S = w * vgx[1152];
                    T0 = vgx[5120] * w;
                    T1 = vgx[5184] * w;
                    T2 = vgx[5248] * w;
                    T3 = vgx[5312] * w;
                    w = dd_cache[640] * vgx[1600];
                    S += w * vgx[1088];
                    T0 += vgx[4864] * w;
                    T1 += vgx[4928] * w;
                    T2 += vgx[4992] * w;
                    T3 += vgx[5056] * w;
                    w = dd_cache[704] * vgx[1664];
                    S += w * vgx[1024];
                    T0 += vgx[4608] * w;
                    T1 += vgx[4672] * w;
                    T2 += vgx[4736] * w;
                    T3 += vgx[4800] * w;
                    w = dd_cache[960] * vgx[1792];
                    S += w * vgx[896];
                    T0 += vgx[4352] * w;
                    T1 += vgx[4416] * w;
                    T2 += vgx[4480] * w;
                    T3 += vgx[4544] * w;
                    w = dd_cache[1024] * vgx[1856];
                    S += w * vgx[832];
                    T0 += vgx[4096] * w;
                    T1 += vgx[4160] * w;
                    T2 += vgx[4224] * w;
                    T3 += vgx[4288] * w;
                    w = dd_cache[1088] * vgx[1920];
                    S += w * vgx[768];
                    T0 += vgx[3840] * w;
                    T1 += vgx[3904] * w;
                    T2 += vgx[3968] * w;
                    T3 += vgx[4032] * w;
                    Ai = vgx[2304];
                    Aj = vgx[2368];
                    Ak = vgx[2432];
                    Al = vgx[2496];
                    vik_xx += (ak2 * (ai2 * vgx[320])) * S;
                    vjk_xx += (ak2 * (aj2 * (vgx[320] - xjxi * vgx[256]))) * S;
                    vil_xx += (al2 * (ai2 * (vgx[320] - xlxk * vgx[64]))) * S;
                    vjl_xx += (al2 * (aj2 * (vgx[320] - xjxi * vgx[256] - xlxk * (vgx[64] - xjxi * vgx[0])))) * S;
                    vik_xy += Ai * T2;
                    vik_yx += Ak * T0;
                    vjk_xy += Aj * T2;
                    vjk_yx += Ak * T1;
                    vil_xy += Ai * T3;
                    vil_yx += Al * T0;
                    vjl_xy += Aj * T3;
                    vjl_yx += Al * T1;
                    w = dd_cache[192] * vgx[1536];
                    S = w * vgx[896];
                    T0 = vgx[4352] * w;
                    T1 = vgx[4416] * w;
                    T2 = vgx[4480] * w;
                    T3 = vgx[4544] * w;
                    w = dd_cache[256] * vgx[1600];
                    S += w * vgx[832];
                    T0 += vgx[4096] * w;
                    T1 += vgx[4160] * w;
                    T2 += vgx[4224] * w;
                    T3 += vgx[4288] * w;
                    w = dd_cache[320] * vgx[1664];
                    S += w * vgx[768];
                    T0 += vgx[3840] * w;
                    T1 += vgx[3904] * w;
                    T2 += vgx[3968] * w;
                    T3 += vgx[4032] * w;
                    Ai = vgx[3072];
                    Aj = vgx[3136];
                    Ak = vgx[3200];
                    Al = vgx[3264];
                    vik_xx += (ak2 * (ai2 * vgx[576]) - 1.0 * (ai2 * vgx[64])) * S;
                    vjk_xx += (ak2 * (aj2 * (vgx[576] - xjxi * vgx[512])) - 1.0 * (aj2 * (vgx[64] - xjxi * vgx[0]))) * S;
                    vil_xx += (al2 * (ai2 * (vgx[576] - xlxk * vgx[320]))) * S;
                    vjl_xx += (al2 * (aj2 * (vgx[576] - xjxi * vgx[512] - xlxk * (vgx[320] - xjxi * vgx[256])))) * S;
                    vik_xy += Ai * T2;
                    vik_yx += Ak * T0;
                    vjk_xy += Aj * T2;
                    vjk_yx += Ak * T1;
                    vil_xy += Ai * T3;
                    vil_yx += Al * T0;
                    vjl_xy += Aj * T3;
                    vjl_yx += Al * T1;
                    w = dd_cache[0] * vgx[384];
                    S = w * vgx[1536];
                    T0 = vgx[5376] * w;
                    T1 = vgx[5440] * w;
                    T2 = vgx[5504] * w;
                    T3 = vgx[5568] * w;
                    w = dd_cache[128] * vgx[320];
                    S += w * vgx[1600];
                    T0 += vgx[5632] * w;
                    T1 += vgx[5696] * w;
                    T2 += vgx[5760] * w;
                    T3 += vgx[5824] * w;
                    w = dd_cache[320] * vgx[256];
                    S += w * vgx[1664];
                    T0 += vgx[5888] * w;
                    T1 += vgx[5952] * w;
                    T2 += vgx[6016] * w;
                    T3 += vgx[6080] * w;
                    w = dd_cache[768] * vgx[128];
                    S += w * vgx[1792];
                    T0 += vgx[6144] * w;
                    T1 += vgx[6208] * w;
                    T2 += vgx[6272] * w;
                    T3 += vgx[6336] * w;
                    w = dd_cache[896] * vgx[64];
                    S += w * vgx[1856];
                    T0 += vgx[6400] * w;
                    T1 += vgx[6464] * w;
                    T2 += vgx[6528] * w;
                    T3 += vgx[6592] * w;
                    w = dd_cache[1088] * vgx[0];
                    S += w * vgx[1920];
                    T0 += vgx[6656] * w;
                    T1 += vgx[6720] * w;
                    T2 += vgx[6784] * w;
                    T3 += vgx[6848] * w;
                    Ai = vgx[3840];
                    Aj = vgx[3904];
                    Ak = vgx[3968];
                    Al = vgx[4032];
                    vik_yy += (ak2 * (ai2 * vgx[1088])) * S;
                    vjk_yy += (ak2 * (aj2 * (vgx[1088] - yjyi * vgx[1024]))) * S;
                    vil_yy += (al2 * (ai2 * (vgx[1088] - ylyk * vgx[832]))) * S;
                    vjl_yy += (al2 * (aj2 * (vgx[1088] - yjyi * vgx[1024] - ylyk * (vgx[832] - yjyi * vgx[768])))) * S;
                    vik_yz += Ai * T2;
                    vik_zy += Ak * T0;
                    vjk_yz += Aj * T2;
                    vjk_zy += Ak * T1;
                    vil_yz += Ai * T3;
                    vil_zy += Al * T0;
                    vjl_yz += Aj * T3;
                    vjl_zy += Al * T1;
                    w = dd_cache[384] * vgx[128];
                    S = w * vgx[1536];
                    T0 = vgx[5376] * w;
                    T1 = vgx[5440] * w;
                    T2 = vgx[5504] * w;
                    T3 = vgx[5568] * w;
                    w = dd_cache[512] * vgx[64];
                    S += w * vgx[1600];
                    T0 += vgx[5632] * w;
                    T1 += vgx[5696] * w;
                    T2 += vgx[5760] * w;
                    T3 += vgx[5824] * w;
                    w = dd_cache[704] * vgx[0];
                    S += w * vgx[1664];
                    T0 += vgx[5888] * w;
                    T1 += vgx[5952] * w;
                    T2 += vgx[6016] * w;
                    T3 += vgx[6080] * w;
                    Ai = vgx[4608];
                    Aj = vgx[4672];
                    Ak = vgx[4736];
                    Al = vgx[4800];
                    vik_yy += (ak2 * (ai2 * vgx[1344]) - 1.0 * (ai2 * vgx[832])) * S;
                    vjk_yy += (ak2 * (aj2 * (vgx[1344] - yjyi * vgx[1280])) - 1.0 * (aj2 * (vgx[832] - yjyi * vgx[768]))) * S;
                    vil_yy += (al2 * (ai2 * (vgx[1344] - ylyk * vgx[1088]))) * S;
                    vjl_yy += (al2 * (aj2 * (vgx[1344] - yjyi * vgx[1280] - ylyk * (vgx[1088] - yjyi * vgx[1024])))) * S;
                    vik_yz += Ai * T2;
                    vik_zy += Ak * T0;
